using System;
using DCore;
using FamObject;

namespace FamService
{
    public class FAM_DeviceVehicleSyncService
    {
        public static bool IsVehicleDeviceCode(string deviceCode)
        {
            if (string.IsNullOrEmpty(deviceCode))
                return false;

            string strCode = deviceCode.ToUpper();
            return strCode.StartsWith("XV-TRON-")
                || strCode.StartsWith("XM-XUC-")
                || strCode.StartsWith("XM-CAU-");
        }

        public static bool SyncVehicle(long deviceId, string deviceCode, string updatedUser, IData idb)
        {
            if (!IsVehicleDeviceCode(deviceCode))
                return true;

            FAM_Device objDevice = new FAM_Device();
            if (idb != null)
                objDevice.IDB = idb;

            return objDevice.ExecNonQuery("FAM_Device_SyncVehicle",
                "@DeviceID", deviceId,
                "@UpdatedUser", updatedUser);
        }
    }
}

